import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import Navbar from '../components/Navbar'; // ✅ If you want the navbar included
import '../styles/ManageGigs.css';

const ManageGigPostings = () => {
    const [searchTerm, setSearchTerm] = useState('');
    const [gigs, setGigs] = useState([]);
    const navigate = useNavigate();

    const fetchGigs = async (username = '') => {
        try {
            const response = await axios.get(`http://localhost:5000/api/gigs`, {
                params: username ? { username } : {}
            });
            setGigs(response.data);
        } catch (error) {
            console.error('Error fetching gigs:', error);
        }
    };

    useEffect(() => {
        fetchGigs(); // initial fetch
    }, []);

    useEffect(() => {
        const delayDebounce = setTimeout(() => {
            fetchGigs(searchTerm.trim());
        }, 300); // debounce search
        return () => clearTimeout(delayDebounce);
    }, [searchTerm]);

    return (
        <>
            <Navbar />
            <div className="manage-gig-container">
                <h2 className="manage-title">Manage Gig Postings</h2>
                <input
                    type="text"
                    className="search-input"
                    placeholder="Search by username..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />

                <div className="gig-list">
                    {gigs.length === 0 ? (
                        <p className="no-gigs-message">No gigs found.</p>
                    ) : (
                        gigs.map((gig) => (
                            <div className="gig-item" key={gig._id}>
                                <div className="gig-title">{gig.title}</div>
                                <div className="gig-subtext">Expires: {gig.expiryDate?.split('T')[0]}</div>
                                <div className="gig-actions">
                                    <button className="view-button" onClick={() => navigate(`/gig/${gig._id}`)}>
                                        View Gig
                                    </button>
                                    <button
                                        className="delete-button"
                                        onClick={async () => {
                                            if (window.confirm("Are you sure you want to delete this gig?")) {
                                                try {
                                                    await axios.delete(`http://localhost:5000/api/gigs/${gig._id}`);
                                                    fetchGigs(searchTerm); // refresh after delete
                                                } catch (error) {
                                                    console.error("Error deleting gig:", error);
                                                }
                                            }
                                        }}
                                    >
                                        Delete Gig
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>
        </>
    );
};

export default ManageGigPostings;
